const assert = require('node:assert/strict');
const {chromium} = require('playwright-core');
(async () => {
  const [base,cookie,customer] = process.argv.slice(2);
  const browser = await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE || '/usr/bin/chromium', headless:true,args:['--no-sandbox']});
  try {
    const context = await browser.newContext();
    await context.addCookies([{name:'session',value:cookie,url:base,httpOnly:true}]);
    const page=await context.newPage();
    assert.equal((await page.goto(base+'/settings')).status(),200);
    await page.locator('[name=business_name]').fill('Browser persisted company');
    await page.locator('[name=timezone]').fill('Pacific/Auckland');
    await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save Company',exact:true}).click()]);
    await page.reload();
    assert.equal(await page.locator('[name=business_name]').inputValue(),'Browser persisted company');
    assert.equal(await page.locator('[name=timezone]').inputValue(),'Pacific/Auckland');
    await page.locator('[name=default_invoice_notes]').fill('Browser future notes');
    await page.locator('[name=invoice_payment_terms]').fill('Browser future terms');
    await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save Documents',exact:true}).click()]);
    await page.goto(base+'/invoices/new');
    assert.equal(await page.locator('[name=notes]').inputValue(),'Browser future notes');
    assert.equal(await page.locator('[name=terms]').inputValue(),'Browser future terms');
	await page.goto(base+`/customers/${customer}/document-defaults`);
	await page.locator('[name=invoice_notes_inherit]').uncheck();
	await page.locator('[name=invoice_notes]').fill('Browser Customer notes');
	await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save Customer defaults',exact:true}).click()]);
	await page.goto(base+'/invoices/new');
	await page.locator('[name=customer_id]').selectOption(customer);
	assert.equal(await page.locator('[name=notes]').inputValue(),'Browser Customer notes');
	await page.locator('[name=notes]').fill('Explicit notes survive customer changes');
	await page.locator('[name=customer_id]').selectOption('');
	await page.locator('[name=customer_id]').selectOption(customer);
	assert.equal(await page.locator('[name=notes]').inputValue(),'Explicit notes survive customer changes');
	await page.locator('[name=title]').fill('Browser persisted invoice');
	await page.locator('[name=terms]').fill('Browser explicit invoice terms');
	const defaultsEditor = await context.newPage();
	await defaultsEditor.goto(base+'/settings');
	await defaultsEditor.locator('[name=default_invoice_notes]').fill('Changed while invoice open');
	await Promise.all([defaultsEditor.waitForNavigation(),defaultsEditor.getByRole('button',{name:'Save Documents',exact:true}).click()]);
	assert.equal(await page.locator('[name=notes]').inputValue(),'Explicit notes survive customer changes');
	assert.equal(await page.locator('[name=terms]').inputValue(),'Browser explicit invoice terms');
	await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save',exact:true}).click()]);
	const invoiceURL = new URL(page.url()).pathname;
	assert.match(invoiceURL,/^\/invoices\/\d+$/);
	await page.goto(base+invoiceURL+'/edit');
	assert.equal(await page.locator('[name=notes]').inputValue(),'Explicit notes survive customer changes');
	assert.equal(await page.locator('[name=terms]').inputValue(),'Browser explicit invoice terms');
	await page.goto(base+invoiceURL+'/pdf/preview');
	await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Generate new PDF version',exact:true}).click()]);
	const version=await page.locator('[name=version]').first().inputValue();
	const savedPDF=await (await context.request.get(base+invoiceURL+'/pdf?version='+version)).body();
    await page.goto(base+'/settings');
    const stale=await context.newPage();
    await stale.goto(base+'/settings');
    await page.locator('[name=invoice_footer]').fill('Concurrent reviewed footer');
    await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save Company',exact:true}).click()]);
    await stale.locator('[name=business_name]').fill('Stale overwrite');
    const response=await Promise.all([stale.waitForNavigation(),stale.getByRole('button',{name:'Save Company',exact:true}).click()]);
    assert.equal(response[0].status(),409);
    await page.goto(base+'/settings');
    assert.equal(await page.locator('[name=business_name]').inputValue(),'Browser persisted company');
	await page.goto(base+invoiceURL+'/pdf/preview');
	assert.match(await page.locator('body').innerText(),/This PDF is stale/);
	assert.equal((await context.request.get(base+invoiceURL+'/pdf?version='+version)).status(),409);
	const oldPDF=await (await context.request.get(base+invoiceURL+'/pdf?version='+version+'&confirm_stale=1')).body();
	assert.deepEqual(oldPDF,savedPDF);
    console.log('Real HTTP/CSRF/PostgreSQL: persisted settings and Customer defaults, explicit-value precedence, persisted invoice/terms, immutable selected PDF after presentation change, stale browser editor rejected.');
  } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
